def live_tensor_storages():
    # Return only allocation metadata. Clearing the temporary object list also
    # prevents the census itself from extending tensor lifetimes after return.
    objects = gc.get_objects()
    storages = {}
    obj = storage = None
    try:
        if len(objects) > 2_000_000:
            raise RuntimeError("Live-object census exceeded its bounded profile")
        for obj in objects:
            if isinstance(obj, torch.Tensor) and obj.layout == torch.strided:
                storage = obj.untyped_storage()
                pointer = storage.data_ptr()
                if pointer:
                    storages[pointer] = storage.nbytes()
        return storages
    finally:
        obj = storage = None
        objects.clear()
